'use strict';

// MODULES //

var path = require( 'path' );
var tape = require( 'tape' );
var readFileSync = require( '@stdlib/fs/read-file' ).sync;
var extract = require( './../lib' );


// VARIABLES //

var fixturesDir = path.join( __dirname, 'fixtures', 'expected' );
var atStdlibRoot = path.resolve( __dirname, '..', '..', '..', '..', '..' );


// FUNCTIONS //

/**
* Validates that the extracted blocks match the expected output.
*
* @private
* @param {Object} t - tape instance
* @param {string} fixtureName - name of the expected JSON file
* @param {string} absolutePath - absolute path to the source file
* @param {string} mode - extraction mode (`src` or `markdown`)
*/
function check( t, fixtureName, absolutePath, mode ) {
	var expectedStr;
	var expected;
	var actual;
	var i;

	// eslint-disable-next-line n/no-sync
	expectedStr = readFileSync( path.join( fixturesDir, fixtureName ), 'utf8' );
	if ( expectedStr instanceof Error ) {
		t.fail( 'Unable to read expected file: ' + fixtureName );
		t.end();
		return;
	}
	expected = JSON.parse( expectedStr );

	// Injects the absolute path back into expected objects...
	for ( i = 0; i < expected.length; i++ ) {
		if ( expected[ i ].file ) {
			expected[ i ].file = absolutePath;
		}
	}

	actual = extract( absolutePath, mode );

	t.deepEqual( JSON.parse( JSON.stringify( actual ) ), expected, 'extracted block matches manually authored expected JSON' );
	t.end();
}


// MAIN //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof extract, 'function', 'main export is a function' );
	t.end();
});

tape( 'extracts correctly for blas_base_caxpy_readme.json', function test( t ) {
	var fpath = path.join( atStdlibRoot, 'blas', 'base', 'caxpy', 'README.md' );
	check( t, 'blas_base_caxpy_readme.json', fpath, 'markdown' );
});

